#include <iostream>
#include <iomanip>

void print_matrix(const float *x, int m, int n) {
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            std::cout << std::fixed << std::setprecision(1) << *(x + i * n + j) << (j + 1 == n ? "" : " ");
        }
        std::cout << "\n";
    }
}

void find_min_matrix(const float *x, int m, int n) {
    float min_val = *x;
    int kmin = 0;
    for (int k = 1; k < m * n; ++k) {
        if (*(x + k) < min_val) {
            min_val = *(x + k);
            kmin = k;
        }
    }
    std::cout << "Min: " << min_val << " at row " << kmin / n << " col " << kmin % n << "\n";
}

void add_matrix(const float *x, const float *y, int m, int n) {
    float *t = new float[m * n];
    for (int k = 0; k < m * n; ++k) {
        *(t + k) = *(x + k) + *(y + k);
    }
    print_matrix(t, m, n);
    delete[] t; // Clean up dynamically allocated memory
}

int main() {
    int m = 2, n = 3;
    float a[2][3] = {
        {5.5f, 2.0f, 8.1f},
        {1.2f, 9.4f, 3.7f}
    };
    float b[2][3] = {
        {1.0f, 3.0f, 2.0f},
        {4.0f, 0.5f, 1.3f}
    };

    find_min_matrix(&a[0][0], m, n);
    std::cout << "Sum matrix:\n";
    add_matrix(&a[0][0], &b[0][0], m, n);
    return 0;
}

#include <iostream>

// Approach 1: Dynamic heap allocation (requires caller to delete[])
int* create_heap_array(int size) {
    int *kq = new int[size];
    for (int i = 0; i < size; ++i) {
        *(kq + i) = (i + 1) * 10;
    }
    return kq;
}

// Approach 2: Output parameter buffer (Caller provides storage)
void fill_matrix_result(const int *src, int *out, int count) {
    for (int i = 0; i < count; ++i) {
        out[i] = src[i] * 2;
    }
}

int main() {
    // Testing Approach 1
    int *arr1 = create_heap_array(3);
    std::cout << "Heap array: ";
    for (int i = 0; i < 3; ++i) {
        std::cout << arr1[i] << (i + 1 == 3 ? "" : " ");
    }
    std::cout << "\n";
    delete[] arr1; // Caller deallocates

    // Testing Approach 2 (Output parameter)
    int input_data[3] = {1, 2, 3};
    int result_buffer[3];
    fill_matrix_result(input_data, result_buffer, 3);

    std::cout << "Output param array: ";
    for (int i = 0; i < 3; ++i) {
        std::cout << result_buffer[i] << (i + 1 == 3 ? "" : " ");
    }
    std::cout << "\n";

    return 0;
}
